arguments.command:
python - <<'PY'
import pandas as pd, numpy as np,pickle
ss=pickle.load(open('structures.pkl','rb'))
for k in [98,83,77]:
 s=ss[200+k-1];print('\n',k,s)
 for el in s.composition.elements:
  for z in [next(z for z,site in enumerate(s) if site.specie==el)]:
   ns=sorted(s.get_neighbors(s[z],5),key=lambda n:n.nn_distance)
   print(el,[(str(n.specie),round(n.nn_distance,3)) for n in ns[:16]])
